'use client'
import Button from '@/components/ui/tailwind/Button'
import Label from '@/components/ui/tailwind/Label'
import Select from '@/components/ui/tailwind/Select'

import { useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'

import ErrorState from '@/components/ui/tailwind/ErrorState'
import { guardarZonaHoraria, useZonaHoraria, zonaHorariaKey } from '@/lib/queries/useZonaHoraria'
import { DEFAULT_TIME_ZONE, TIME_ZONE_GROUPS } from '@/lib/timeZone'
import { getUserError } from '@/lib/errors/userError'
import { showSuccess } from '@/lib/services/errorToast'

/** Editor administrativo de una sola preferencia. La API valida el rol y
 * devuelve únicamente esta clave, sin abrir el resto de la configuración.
 */
export default function ZonaHorariaEditor() {
  const queryClient = useQueryClient()
  const zonaQuery = useZonaHoraria()
  const [borrador, setBorrador] = useState<string | null>(null)
  const [guardando, setGuardando] = useState(false)
  const [errorGuardar, setErrorGuardar] = useState<string | null>(null)

  if (zonaQuery.error) return <ErrorState error={zonaQuery.error} title="No se pudo cargar la zona horaria" onRetry={() => void zonaQuery.refetch()} retrying={zonaQuery.isFetching} />

  const actual = zonaQuery.data ?? DEFAULT_TIME_ZONE
  const seleccion = borrador ?? actual
  const guardar = async () => {
    setGuardando(true)
    setErrorGuardar(null)
    try {
      const guardada = await guardarZonaHoraria(seleccion)
      queryClient.setQueryData(zonaHorariaKey, guardada)
      setBorrador(null)
      await queryClient.invalidateQueries({ queryKey: ['configuraciones_sistema'] })
      showSuccess('Zona horaria actualizada')
    } catch (error) {
      setErrorGuardar(getUserError(error, 'No se pudo guardar la zona horaria').message)
    } finally {
      setGuardando(false)
    }
  }

  const enLista = TIME_ZONE_GROUPS.some((grupo) => grupo.options.some((opcion) => opcion.value === actual))
  return <section className="tw:mb-6 tw:rounded tw:border tw:bg-surface tw:p-6" aria-labelledby="titulo-zona-horaria">
    <h3 id="titulo-zona-horaria" className="tw:text-xl tw:mb-2">Zona horaria del dashboard</h3>
    <p className="tw:text-muted tw:mb-4">Define el año y los meses de los gráficos, y cómo se muestran las fechas y los plazos del dashboard.</p>
    <div className="tw:flex tw:items-end tw:gap-4 tw:flex-wrap">
      <div style={{ minWidth: 240, maxWidth: 360, flex: '1 1 240px' }}>
        <Label htmlFor="zona-horaria-sistema">Región y país</Label>
        <Select id="zona-horaria-sistema" value={seleccion} disabled={zonaQuery.isPending || guardando}
          onChange={(evento) => { setBorrador(evento.target.value); setErrorGuardar(null) }}>
          {!enLista && <option value={actual}>Actual: {actual}</option>}
          {TIME_ZONE_GROUPS.map((grupo) => <optgroup key={grupo.label} label={grupo.label}>
            {grupo.options.map((opcion) => <option key={opcion.value} value={opcion.value}>{opcion.label} ({opcion.value})</option>)}
          </optgroup>)}
        </Select>
      </div>
      <Button variant="primary" type="button" onClick={() => void guardar()}
        disabled={zonaQuery.isPending || guardando || seleccion === actual}>
        {guardando ? 'Guardando…' : 'Guardar zona horaria'}
      </Button>
    </div>
    {errorGuardar && <p role="alert" className="tw:text-qms-danger tw:mt-4 tw:mb-0">{errorGuardar}</p>}
    <p className="tw:text-sm tw:text-muted tw:mt-4 tw:mb-0">Actual: {actual}. Los plazos se muestran según esta zona; las reglas de SLA guardadas no se modifican.</p>
  </section>
}

