'use client'

import { useEffect } from 'react'

export default function QuejasError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error('[quejas-error]', error)
  }, [error])

  return (
    <div className="min-h-[60vh] flex items-center justify-center p-4">
      <div className="bg-white rounded-lg shadow-lg p-8 max-w-md w-full text-center">
        <div className="text-4xl mb-4">⚠️</div>
        <h1 className="text-xl font-semibold text-gray-800 mb-2">
          Error en Quejas
        </h1>
        <p className="text-gray-500 mb-6">
          No se pudieron cargar las quejas. Por favor intentá de nuevo.
        </p>
        <button
          onClick={reset}
          className="px-4 py-2 bg-[#0d6efd] text-white rounded-md hover:bg-[#0b5ed7] transition-colors"
        >
          Intentar de nuevo
        </button>
      </div>
    </div>
  )
}

app/quejas/page.tsx:
'use client'

import { useState, useMemo, useRef, useDeferredValue, useCallback } from 'react'
import { Plus, Search, Loader2, CheckCircle2, ThumbsUp, CalendarRange, Eye } from 'lucide-react'
import { useQueryClient } from '@tanstack/react-query'
import type { Queja } from '@/lib/types'
import { useQuejas, useSLAConfig, useQuejasEstadisticas, quejasEstadisticasKey, fetchQuejaAdjuntos, quejaAdjuntosKey } from '@/lib/queries/useQuejas'
import { queryKeys } from '@/lib/queries/queryKeys'
import { useCatalogoTipo } from '@/lib/queries/useCatalogos'
import Badge from '@/components/ui/Badge'
import Select from '@/components/ui/Select'
import PageHeader from '@/components/ui/PageHeader'
import EmptyState from '@/components/ui/EmptyState'
import StatCard from '@/components/StatCard'
import Pagination from '@/components/ui/Pagination'
import NuevaQuejaModal from './components/NuevaQuejaModal'
import QuejaDetalleModal from './components/QuejaDetalleModal'
import { useRealtimeSubscription } from '@/hooks/useRealtimeSubscription'
import { useHoverPrefetch } from '@/hooks/useHoverPrefetch'
import { useQuejasVistas } from '@/hooks/useQuejasVistas'
import { useAuthStore } from '@/lib/store/auth-store'
import { prioridadVariant, estadoVariant } from '@/lib/constants/variants'

export default function QuejasPage() {
  const [search, setSearch] = useState('')
  const deferredSearch = useDeferredValue(search)
  const [filtroEstado, setFiltroEstado] = useState('')
  const [filtroPrioridad, setFiltroPrioridad] = useState('')
  const [nuevaOpen, setNuevaOpen] = useState(false)
  const [detalleOpen, setDetalleOpen] = useState<Queja | null>(null)
  const [page, setPage] = useState(0)
  const [ahora] = useState(() => Date.now())
  const pageSize = 25
  const tableRef = useRef<HTMLDivElement>(null)
  const user = useAuthStore((s) => s.user)
  const { esVista, marcarVista, marcarTodasVistas, contarNoVistas } = useQuejasVistas(user?.id)

  const { data, isLoading: loading, error, refetch } = useQuejas({
    page,
    pageSize,
    search: deferredSearch,
    estado: filtroEstado,
    prioridad: filtroPrioridad,
  })
  const quejas = useMemo(() => data?.data ?? [], [data?.data])
  const totalCount = data?.count ?? 0
  const queryClient = useQueryClient()
  const invalidateQuejas = () => {
    queryClient.invalidateQueries({ queryKey: queryKeys.quejas })
    queryClient.invalidateQueries({ queryKey: queryKeys.dashboard })
  }
  const { data: categorias = [] } = useCatalogoTipo('categoria_queja')
  const { data: estados = [] } = useCatalogoTipo('estado_queja')
  const { data: prioridades = [] } = useCatalogoTipo('prioridad')
  const { data: slaConfigs = [] } = useSLAConfig('quejas')
  const { data: estadisticas } = useQuejasEstadisticas()

  useRealtimeSubscription({
    table: 'quejas',
    invalidateKeys: [
      [...queryKeys.quejas],
      quejasEstadisticasKey,
      [...queryKeys.dashboard],
    ],
  })

  const mesActual = estadisticas?.mesActual ?? 0
  const slaMap = useMemo(() => {
    const m: Record<string, { dias_alerta: number; dias_vencimiento: number }> = {}
    for (const s of slaConfigs) m[s.prioridad] = s
    return m
  }, [slaConfigs])

  function calcularSLA(fecha: string, prioridad: string, estado: string): { label: string; variant: string } {
    if (estadoVariant[estado] === 'green') return { label: 'Completado', variant: 'green' }
    const dias = Math.floor((ahora - new Date(fecha).getTime()) / 86400000)
    const sla = slaMap[prioridad]
    if (sla) {
      if (dias <= sla.dias_alerta) return { label: `${dias}d`, variant: 'green' }
      if (dias <= sla.dias_vencimiento) return { label: `${dias}d`, variant: 'amber' }
      return { label: `${dias}d`, variant: 'red' }
    }
    if (dias <= 3) return { label: `${dias}d`, variant: 'green' }
    if (dias <= 7) return { label: `${dias}d`, variant: 'amber' }
    return { label: `${dias}d`, variant: 'red' }
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))
  const quejaIds = useMemo(() => quejas.map((q) => q.id), [quejas])
  const noVistasCount = contarNoVistas(quejaIds)

  const prefetch = useHoverPrefetch()

  const handleAbrirDetalle = useCallback((q: Queja) => {
    setDetalleOpen(q)
    // Marcar como visto en segundo plano — no bloquea la apertura
    requestAnimationFrame(() => marcarVista(q.id))
  }, [marcarVista])

  return (
    <div className="flex h-full flex-col">
      <PageHeader title="Quejas" description="Registro y seguimiento de quejas">
        <button onClick={() => setNuevaOpen(true)} className="inline-flex h-[38px] shrink-0 items-center gap-1.5 rounded-button border-0 bg-qms-primary px-3.5 text-sm font-medium text-white hover:bg-qms-primary-hover">
          <Plus className="h-4 w-4" /> Nueva queja
        </button>
      </PageHeader>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 mb-4 shrink-0">
        <StatCard
          title="Resueltas a tiempo"
          value={`${estadisticas?.pctATiempo ?? 0}%`}
          icon={<CheckCircle2 className="h-5 w-5" />}
          color="green"
          subtitle={`vs fecha_sla de las resueltas/finalizadas (${estadisticas?.resueltasTotal ?? 0} evaluadas)`}
        />
        <StatCard
          title="Procedencia"
          value={`${estadisticas?.pctProcedencia ?? 0}%`}
          icon={<ThumbsUp className="h-5 w-5" />}
          color="blue"
          subtitle={`de quejas decididas no son "No Procede" (${estadisticas?.totalConDecision ?? 0} decididas, ${estadisticas ? (estadisticas.totalConDecision - estadisticas.procedentes) : 0} no proceden)`}
        />
        <StatCard
          title="Quejas este mes"
          value={mesActual}
          icon={<CalendarRange className="h-5 w-5" />}
          color="purple"
          subtitle={new Date(ahora).toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
        />
        <StatCard
          title="Total quejas"
          value={totalCount}
          icon={<Search className="h-5 w-5" />}
          color="red"
          subtitle={`${totalCount} registradas`}
        />
      </div>

      <div className="flex items-center gap-2 mb-3 shrink-0">
        {noVistasCount > 0 && (
          <button
            onClick={() => marcarTodasVistas(quejaIds)}
            className="inline-flex h-[34px] shrink-0 items-center gap-1.5 rounded-button border border-qms-border bg-qms-surface px-2.5 text-xs font-medium text-gray-600 transition-colors hover:bg-qms-hover-bg"
            title="Marcar todas las quejas visibles como vistas"
          >
            <Eye className="h-3.5 w-3.5" />
            {noVistasCount} sin ver
          </button>
        )}
        <div className="relative flex-1 min-w-0">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
          <input
            placeholder="Buscar folio o cliente..."
            className="h-[38px] w-full rounded-button border border-qms-border bg-qms-surface pl-9 pr-3 text-sm outline-none focus:border-qms-primary focus:ring-1 focus:ring-qms-primary"
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(0) }}
          />
        </div>
        <Select value={filtroEstado} onChange={(e) => { setFiltroEstado(e.target.value); setPage(0) }}>
          <option value="">Estados</option>
          {estados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
        </Select>
        <Select value={filtroPrioridad} onChange={(e) => { setFiltroPrioridad(e.target.value); setPage(0) }}>
          <option value="">Prioridad</option>
          {prioridades.map((p) => <option key={p.valor} value={p.valor}>{p.valor}</option>)}
        </Select>
      </div>

      <div ref={tableRef} className="min-h-0 flex-1 overflow-auto rounded-card border border-qms-border">
        {loading ? (
          <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
        ) : error ? (
          <div className="flex min-h-[300px] flex-col items-center justify-center gap-3">
            <p className="text-sm text-gray-500">No se pudieron cargar las quejas.</p>
            <button onClick={() => refetch()} className="rounded-button border-0 bg-qms-primary px-3 py-1.5 text-sm font-medium text-white hover:bg-qms-primary-hover">Reintentar</button>
          </div>
        ) : (
          <table className="w-full select-text text-left text-sm">
            <thead>
              <tr className="sticky top-0 z-10 bg-qms-header">
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap">Folio</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap min-w-[160px]">Cliente</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap min-w-[140px]">Categoría</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap">Prioridad</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap">Estado</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap">SLA</th>
                <th className="px-3 py-2.5 text-left font-semibold text-white whitespace-nowrap">Fecha</th>
              </tr>
            </thead>
            <tbody>
              {quejas.length === 0 ? (
                <EmptyState message="No se encontraron quejas" />
              ) : (
                quejas.map((q) => {
                  const sla = calcularSLA(q.fecha, q.prioridad, q.estado)
                  const vista = esVista(q.id)
                  return (
                    <tr
                      key={q.id}
                      onClick={() => handleAbrirDetalle(q)}
                      className={`cursor-pointer border-b border-gray-200 transition-colors hover:bg-gray-50 ${vista ? '' : 'bg-blue-50/50'}`}
                      onMouseEnter={() => {
                        prefetch({
                          queryKey: quejaAdjuntosKey(q.id),
                          queryFn: () => fetchQuejaAdjuntos(q.id),
                          staleTime: Infinity,
                        })
                      }}
                    >
                      <td className="px-3 py-2.5 align-middle"><span className={`font-mono text-sm ${vista ? 'font-medium' : 'font-bold text-gray-900'}`}>{q.folio}</span></td>
                      <td className={`px-3 py-2.5 align-middle ${vista ? 'font-medium text-gray-900' : 'font-bold text-gray-900'}`}>{q.cliente_nombre}</td>
                      <td className={`px-3 py-2.5 align-middle ${vista ? 'text-gray-600' : 'font-medium text-gray-800'}`}>{q.categoria}</td>
                      <td className="px-3 py-2.5 align-middle"><Badge variant={prioridadVariant[q.prioridad] || 'gray'}>{q.prioridad}</Badge></td>
                      <td className="px-3 py-2.5 align-middle"><Badge variant={estadoVariant[q.estado] || 'gray'}>{q.estado}</Badge></td>
                      <td className="px-3 py-2.5 align-middle"><Badge variant={sla.variant}>{sla.label}</Badge></td>
                      <td className={`px-3 py-2.5 align-middle whitespace-nowrap ${vista ? 'text-gray-500' : 'font-medium text-gray-700'}`}>{new Date(q.fecha).toLocaleDateString('es-ES')}</td>
                    </tr>
                  )
                })
              )}
            </tbody>
          </table>
        )}
      </div>

      {!loading && <Pagination page={page} count={totalCount} busy={loading} onChange={setPage} />}

      <NuevaQuejaModal open={nuevaOpen} onClose={() => setNuevaOpen(false)} onCreated={() => { invalidateQuejas() }} categorias={categorias} prioridades={prioridades} />
      <QuejaDetalleModal queja={detalleOpen} onClose={() => setDetalleOpen(null)} onUpdated={() => { invalidateQuejas() }} prioridades={prioridades} categorias={categorias} />
    </div>
  )
}

app/reporteria/components/GeneradorInfor:
'use client'

import { useState, useEffect } from 'react'
import {
  MessageSquareWarning, ClipboardList, FileCheck2,
  ShieldAlert, ClipboardCheck, SearchCheck, Loader2,
  ChevronRight, ChevronLeft, Check, Printer, X,
} from 'lucide-react'
import Modal from '@/components/Modal'
import Select from '@/components/ui/Select'
import Button from '@/components/ui/Button'
import Badge from '@/components/ui/Badge'
import { showError } from '@/lib/services/errorToast'
import { supabase } from '@/lib/supabase'

interface Props {
  open: boolean
  onClose: () => void
  moduloInicial: string | null
}

const modulos = [
  { value: 'quejas', label: 'Quejas', icon: MessageSquareWarning },
  { value: 'sacp', label: 'SACP', icon: ClipboardList },
  { value: 'documentos', label: 'Documentos', icon: FileCheck2 },
  { value: 'riesgos', label: 'Riesgos', icon: ShieldAlert },
  { value: 'auditorias', label: 'Auditorías', icon: ClipboardCheck },
  { value: 'revision_direccion', label: 'Revisión por Dirección', icon: SearchCheck },
]

const tablaPorModulo: Record<string, string> = {
  quejas: 'quejas',
  sacp: 'acciones',
  documentos: 'documentos',
  riesgos: 'riesgos',
  auditorias: 'auditorias',
  revision_direccion: 'reuniones',
}

interface FilaInforme { id: string; estado: string; [key: string]: unknown }

interface CatalogoItem { valor: string; color: string }

export default function GeneradorInformeModal(props: Props) {
  if (!props.open) return null
  return <ContenidoInforme key={props.moduloInicial ?? 'nuevo'} {...props} />
}

function ContenidoInforme({ open, onClose, moduloInicial }: Props) {
  const [paso, setPaso] = useState(moduloInicial ? 2 : 1)
  const [modulo, setModulo] = useState(moduloInicial ?? '')
  const [incluir, setIncluir] = useState({ tabla: true, resumen: true, vencidos: false, distribucion: false })
  const [fechaDesde, setFechaDesde] = useState('')
  const [fechaHasta, setFechaHasta] = useState('')
  const [filterEstado, setFilterEstado] = useState('')
  const [filterPrioridad, setFilterPrioridad] = useState('')
  const [filterTipo, setFilterTipo] = useState('')
  const [catalogoEstados, setCatalogoEstados] = useState<CatalogoItem[]>([])
  const [catalogoPrioridades, setCatalogoPrioridades] = useState<CatalogoItem[]>([])
  const [catalogoTipos, setCatalogoTipos] = useState<CatalogoItem[]>([])
  const [resultados, setResultados] = useState<FilaInforme[]>([])
  const [loading, setLoading] = useState(false)

  useEffect(() => {
    if (paso !== 2) return
    const cargarCatalogos = async () => {
      setCatalogoEstados([])
      setCatalogoPrioridades([])
      setCatalogoTipos([])
      const tipoEstadoMap: Record<string, string> = {
        quejas: 'estado_queja', sacp: 'estado_sacp', documentos: 'estado_documento',
        auditorias: 'estado_auditoria', riesgos: '', revision_direccion: '',
      }
      const tipoPrioridadMap: Record<string, string> = { quejas: 'prioridad' }
      const tipoCatMap: Record<string, string> = { sacp: 'tipo_sacp' }

      const promises: PromiseLike<CatalogoItem[]>[] = []
      if (tipoEstadoMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoEstadoMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      if (tipoPrioridadMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoPrioridadMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      if (tipoCatMap[modulo]) promises.push(
        supabase.from('catalogos').select('valor,color').eq('tipo', tipoCatMap[modulo]).eq('modulo', modulo).or('activo.is.null,activo.eq.true').order('orden').then(r => r.data || [])
      )
      const results = await Promise.all(promises)
      let idx = 0
      if (tipoEstadoMap[modulo]) { setCatalogoEstados(results[idx]); idx++ }
      if (tipoPrioridadMap[modulo]) { setCatalogoPrioridades(results[idx]); idx++ }
      if (tipoCatMap[modulo]) { setCatalogoTipos(results[idx]); idx++ }
    }
    cargarCatalogos()
  }, [paso, modulo])

  const generarInforme = async () => {
    const tabla = tablaPorModulo[modulo]
    if (!tabla) return
    setLoading(true)
    try {
      const fechaPorModulo: Record<string, string> = { quejas: 'fecha', sacp: 'fecha_apertura', documentos: 'created_at', riesgos: 'fecha_identificacion', auditorias: 'fecha_inicio', revision_direccion: 'fecha_programada' }
      const filas: FilaInforme[] = []
      const batchSize = 500
      for (let desde = 0; ; desde += batchSize) {
        let query = supabase.from(tabla).select('*', { count: 'exact' })
        if (fechaDesde) query = query.gte(fechaPorModulo[modulo], fechaDesde)
        if (fechaHasta) {
          const siguiente = new Date(fechaHasta + 'T00:00:00Z')
          siguiente.setUTCDate(siguiente.getUTCDate() + 1)
          query = query.lt(fechaPorModulo[modulo], siguiente.toISOString().slice(0, 10))
        }
        if (filterEstado) query = query.eq('estado', filterEstado)
        if (filterPrioridad && modulo === 'quejas') query = query.eq('prioridad', filterPrioridad)
        if (filterTipo) query = query.eq('tipo', filterTipo)
        const { data, error, count } = await query.order('id').range(desde, desde + batchSize - 1)
        if (error) throw error
        if ((count ?? 0) > 5000) throw new Error('El informe supera 5000 registros. Ajustá las fechas o filtros para generarlo.')
        const batch = (data ?? []) as FilaInforme[]
        filas.push(...batch)
        if (batch.length < batchSize || filas.length >= (count ?? Infinity)) break
      }
      setResultados(filas)
      setPaso(3)
    } catch (error) {
      showError(error instanceof Error ? error : new Error(String(error)), 'No se pudo generar el informe')
    } finally { setLoading(false) }
  }

  const columnsPorModulo: Record<string, { key: string; label: string }[]> = {
    quejas: [
      { key: 'folio', label: 'Folio' },
      { key: 'cliente_nombre', label: 'Cliente' },
      { key: 'categoria', label: 'Categoría' },
      { key: 'prioridad', label: 'Prioridad' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha', label: 'Fecha' },
    ],
    sacp: [
      { key: 'folio', label: 'Folio' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'descripcion', label: 'Descripción' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_limite', label: 'Fecha Límite' },
    ],
    documentos: [
      { key: 'codigo_doc', label: 'Código' },
      { key: 'titulo', label: 'Título' },
      { key: 'version_actual', label: 'Versión' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_publicacion', label: 'Fecha Publicación' },
    ],
    riesgos: [
      { key: 'folio', label: 'Folio' },
      { key: 'descripcion', label: 'Descripción' },
      { key: 'impacto', label: 'Impacto' },
      { key: 'probabilidad', label: 'Probabilidad' },
      { key: 'estado', label: 'Estado' },
    ],
    auditorias: [
      { key: 'folio', label: 'Folio' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'proceso_area', label: 'Proceso/Área' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_inicio', label: 'Fecha Inicio' },
    ],
    revision_direccion: [
      { key: 'titulo', label: 'Título' },
      { key: 'tipo', label: 'Tipo' },
      { key: 'estado', label: 'Estado' },
      { key: 'fecha_programada', label: 'Fecha' },
    ],
  }

  const campoDistribucion: Record<string, string> = {
    quejas: 'categoria',
    documentos: 'categoria',
    riesgos: 'tipo',
    auditorias: 'tipo',
    sacp: 'tipo',
    revision_direccion: 'tipo',
  }

  const campoVencido: Record<string, string> = {
    quejas: 'fecha_sla',
    sacp: 'fecha_limite',
    documentos: 'fecha_publicacion',
    auditorias: 'fecha_inicio',
    riesgos: 'fecha_identificacion',
    revision_direccion: 'fecha_programada',
  }

  const cellValue = (row: FilaInforme, key: string) => {
    const v = row[key]
    if (v == null || v === '') return '—'
    if (key === 'descripcion' && typeof v === 'string' && v.length > 60) return v.slice(0, 60) + '…'
    if (key === 'impacto' || key === 'probabilidad') return String(v)
    if (typeof v === 'string' && v.includes('T')) return new Date(v).toLocaleDateString('es-ES')
    return String(v)
  }

  return (
    <Modal open={open} onClose={onClose} title="Generar Informe" size="lg">
      <div className="informe-content">
        {paso < 3 && (
          <div className="flex items-center gap-2 mb-4">
            {[1, 2].map((p) => (
              <div key={p} className="flex items-center gap-1.5">
                <div
                  className={`flex h-[22px] w-[22px] items-center justify-center rounded-button text-xs font-semibold text-white ${paso >= p ? 'bg-qms-primary' : 'bg-gray-300'}`}
                >
                  {p}
                </div>
                <span className={`text-sm ${paso >= p ? 'text-qms-dark' : 'text-gray-400'}`}>
                  {p === 1 ? 'Selección' : 'Filtros'}
                </span>
                {p < 2 && <span className="mx-1 text-gray-300"><ChevronRight className="inline h-3 w-3" /></span>}
              </div>
            ))}
          </div>
        )}

        {paso === 1 && (
          <div className="space-y-4">
            <div>
              <p className="mb-2 text-sm font-medium text-qms-dark">Módulo</p>
              <div className="grid grid-cols-2 gap-2">
                {modulos.map((m) => {
                  const Icon = m.icon
                  const selected = modulo === m.value
                  return (
                    <button
                      key={m.value}
                      onClick={() => setModulo(m.value)}
                      className={`flex cursor-pointer items-center gap-2.5 rounded-card border p-3 text-left text-sm transition-all ${selected ? 'border-2 border-qms-primary bg-qms-primary' : 'border-qms-border bg-qms-surface hover:bg-gray-50'}`}
                    >
                      <div
                        className={`flex h-[34px] w-[34px] shrink-0 items-center justify-center rounded-card ${selected ? 'bg-white/20' : 'bg-soft-blue-bg'}`}
                      >
                        <Icon className={`h-4 w-4 ${selected ? 'text-white' : 'text-qms-primary'}`} />
                      </div>
                      <span className={`font-medium ${selected ? 'text-white' : 'text-qms-dark'}`}>{m.label}</span>
                      {selected && <span className="ml-auto text-xs font-semibold text-white/80"><Check className="inline h-3 w-3" /></span>}
                    </button>
                  )
                })}
              </div>
            </div>
            <div>
              <label className="mb-1 block text-sm font-medium text-qms-dark">¿Qué incluir en el informe?</label>
              <div className="space-y-2">
                {[
                  { key: 'tabla', label: 'Tabla de registros' },
                  { key: 'resumen', label: 'Resumen por estado' },
                  { key: 'vencidos', label: 'Registros vencidos / por vencer' },
                  { key: 'distribucion', label: 'Distribución por categoría/tipo' },
                ].map((item) => (
                  <label key={item.key} className="flex items-center gap-2 text-sm cursor-pointer">
                    <input
                      type="checkbox"
                      checked={incluir[item.key as keyof typeof incluir]}
                      onChange={(e) => setIncluir({ ...incluir, [item.key]: e.target.checked })}
                      className="rounded border-gray-300"
                    />
                    {item.label}
                  </label>
                ))}
              </div>
            </div>
            <div className="flex justify-end pt-2">
                <Button onClick={() => { if (modulo) { setPaso(2); setFilterEstado(''); setFilterPrioridad(''); setFilterTipo('') } }}>
                  Siguiente <ChevronRight className="h-4 w-4 inline" />
                </Button>
            </div>
          </div>
        )}

        {paso === 2 && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Desde</label>
                <input
                  type="date"
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm"
                  value={fechaDesde}
                  onChange={(e) => setFechaDesde(e.target.value)}
                />
              </div>
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Hasta</label>
                <input
                  type="date"
                  className="w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-sm"
                  value={fechaHasta}
                  onChange={(e) => setFechaHasta(e.target.value)}
                />
              </div>
            </div>
            {modulo === 'quejas' && catalogoEstados.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Estado</label>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'quejas' && catalogoPrioridades.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Prioridad</label>
                <Select className="w-full" value={filterPrioridad} onChange={(e) => setFilterPrioridad(e.target.value)}>
                  <option value="">Todas</option>
                  {catalogoPrioridades.map((p) => <option key={p.valor} value={p.valor}>{p.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'sacp' && catalogoEstados.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Estado</label>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'sacp' && catalogoTipos.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Tipo</label>
                <Select className="w-full" value={filterTipo} onChange={(e) => setFilterTipo(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoTipos.map((t) => <option key={t.valor} value={t.valor}>{t.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'auditorias' && catalogoEstados.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Estado</label>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}
            {modulo === 'documentos' && catalogoEstados.length > 0 && (
              <div>
                <label className="mb-1 block text-sm font-medium text-qms-dark">Estado</label>
                <Select className="w-full" value={filterEstado} onChange={(e) => setFilterEstado(e.target.value)}>
                  <option value="">Todos</option>
                  {catalogoEstados.map((e) => <option key={e.valor} value={e.valor}>{e.valor}</option>)}
                </Select>
              </div>
            )}

            <div className="flex items-center justify-between pt-2">
              <Button variant="secondary" onClick={() => setPaso(1)}><ChevronLeft className="h-4 w-4 inline" /> Atrás</Button>
              <Button onClick={generarInforme}>Generar informe <ChevronRight className="h-4 w-4 inline" /></Button>
            </div>
          </div>
        )}

        {paso === 3 && (
          <div>
            {loading ? (
              <div className="flex min-h-[200px] items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-qms-primary" />
              </div>
            ) : (
              <div className="space-y-5">
                <div className="text-center pb-3 border-b border-gray-200">
                  <h2 className="m-0 text-xl font-bold text-qms-dark">Informe de {modulos.find(m => m.value === modulo)?.label}</h2>
                  <p className="m-0 mt-1 text-sm text-qms-muted">Ente Costarricense de Acreditación</p>
                  <p className="m-0 text-xs text-gray-400">
                    Generado: {new Date().toLocaleDateString('es-ES', { year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                    {fechaDesde && ` · Período: ${new Date(fechaDesde).toLocaleDateString('es-ES')} - ${new Date(fechaHasta).toLocaleDateString('es-ES')}`}
                  </p>
                </div>

                {incluir.resumen && resultados.length > 0 && (
                  <div>
                    <h3 className="mb-2 text-sm font-semibold text-qms-dark">Resumen por Estado</h3>
                    <div className="flex gap-3 flex-wrap">
                      <div className="min-w-20 rounded-card border border-qms-border bg-qms-surface px-4 py-2 text-center">
                        <p className="m-0 text-2xl font-bold text-qms-primary">{resultados.length}</p>
                        <p className="m-0 text-xs text-qms-muted">Total</p>
                      </div>
                      {Object.entries(
                        resultados.reduce((acc: Record<string, number>, r) => {
                          acc[r.estado] = (acc[r.estado] || 0) + 1
                          return acc
                        }, {})
                      ).map(([estado, count]) => (
                        <div key={estado} className="rounded-card border border-qms-border bg-qms-surface px-4 py-2 text-center min-w-[80px]">
                          <p className="text-2xl font-bold m-0 text-qms-dark">{count}</p>
                          <p className="text-xs m-0 text-qms-muted">{estado}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {incluir.distribucion && resultados.length > 0 && campoDistribucion[modulo] && (
                  <div>
                    <h3 className="text-sm font-semibold mb-2 text-qms-dark">
                      Distribución por {modulo === 'quejas' ? 'Categoría' : 'Tipo'}
                    </h3>
                    <div className="rounded-lg border border-qms-border bg-white">
                      <table className="w-full select-text text-sm">
                        <thead>
                          <tr className="bg-qms-header">
                            <th className="px-3 py-2 text-left font-semibold text-white">
                              {modulo === 'quejas' ? 'Categoría' : 'Tipo'}
                            </th>
                            <th className="px-3 py-2 text-right font-semibold text-white">Cantidad</th>
                          </tr>
                        </thead>
                        <tbody>
                          {Object.entries(
                            resultados.reduce((acc: Record<string, number>, r) => {
                              const val = String(r[campoDistribucion[modulo]] || 'Sin asignar')
                              acc[val] = (acc[val] || 0) + 1
                              return acc
                            }, {})
                          ).map(([cat, count]) => (
                            <tr key={cat} className="border-b border-gray-200">
                              <td className="px-3 py-1.5">{cat}</td>
                              <td className="px-3 py-1.5 text-right font-semibold">{count}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                {incluir.tabla && (
                  <div>
                    <h3 className="text-sm font-semibold mb-2 text-qms-dark">Registros</h3>
                    <div className="rounded-lg border border-qms-border bg-white">
                      <table className="w-full select-text text-sm">
                        <thead>
                          <tr className="bg-qms-header">
                            {columnsPorModulo[modulo]?.map((col) => (
                              <th key={col.key} className="px-3 py-2 text-left font-semibold text-white whitespace-nowrap">
                                {col.label}
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {resultados.length === 0 ? (
                            <tr><td colSpan={columnsPorModulo[modulo]?.length || 1} className="px-3 py-8 text-center text-gray-500">Sin registros</td></tr>
                          ) : (
                            resultados.map((row: FilaInforme) => (
                              <tr key={row.id} className="border-b border-gray-200">
                                {columnsPorModulo[modulo]?.map((col) => (
                                  <td key={col.key} className="px-3 py-1.5 align-middle">
                                    {col.key === 'prioridad' || col.key === 'estado' ? (
                                      <Badge variant="gray">{cellValue(row, col.key)}</Badge>
                                    ) : (
                                      <span>{cellValue(row, col.key)}</span>
                                    )}
                                  </td>
                                ))}
                              </tr>
                            ))
                          )}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                {incluir.vencidos && resultados.length > 0 && campoVencido[modulo] && (
                  <div>
                    <h3 className="text-sm font-semibold mb-2 text-qms-danger">Registros Vencidos / Por Vencer</h3>
                    <div className="rounded-lg border bg-white border-qms-danger">
                      <table className="w-full select-text text-sm">
                        <thead>
                          <tr className="bg-qms-header">
                            {columnsPorModulo[modulo]?.map((col) => (
                              <th key={col.key} className="px-3 py-2 text-left font-semibold text-white whitespace-nowrap">
                                {col.label}
                              </th>
                            ))}
                          </tr>
                        </thead>
                        <tbody>
                          {(() => {
                            const hoy = new Date()
                            const vencidos = resultados.filter((r: FilaInforme) => {
                              const fechaCampo = campoVencido[modulo]
                              const val = r[fechaCampo]
                              if (!val || ['Cerrada', 'Finalizado', 'No Procede'].includes(r.estado)) return false
                              return new Date(String(val)) < hoy
                            })
                            return vencidos.length === 0 ? (
                              <tr><td colSpan={columnsPorModulo[modulo]?.length || 1} className="px-3 py-8 text-center text-gray-500">Sin registros vencidos</td></tr>
                            ) : (
                              vencidos.map((row: FilaInforme) => (
                                <tr key={row.id} className="border-b border-gray-200 bg-soft-red-bg">
                                  {columnsPorModulo[modulo]?.map((col) => (
                                    <td key={col.key} className="px-3 py-1.5 align-middle text-qms-danger">
                                      {cellValue(row, col.key)}
                                    </td>
                                  ))}
                                </tr>
                              ))
                            )
                          })()}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}

                <div className="flex items-center justify-between pt-3 border-t border-gray-200 no-print">
                  <Button variant="secondary" onClick={() => setPaso(2)}><ChevronLeft className="h-4 w-4 inline" /> Atrás</Button>
                  <div className="flex items-center gap-2">
                    <Button variant="secondary" onClick={() => window.print()}><Printer className="h-4 w-4 inline" /> Imprimir</Button>
                    <Button variant="secondary" onClick={onClose}><X className="h-4 w-4 inline" /> Cerrar</Button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </Modal>
  )
}

