app/riesgos/page.tsx:
'use client'

import { useState } from 'react'
import { Plus, Loader2 } from 'lucide-react'
import { useQueryClient } from '@tanstack/react-query'
import { useRiesgos, riesgosKey, useMatrizRiesgos } from '@/lib/queries/useRiesgos'
import Pagination from '@/components/ui/Pagination'
import PageHeader from '@/components/ui/PageHeader'
import { Table, TableHead, TableHeaderCell, TableRow, TableCell } from '@/components/ui/Table'
import Badge from '@/components/ui/Badge'
import EmptyState from '@/components/ui/EmptyState'

import Button from '@/components/ui/Button'
import NuevoRiesgoModal from './components/NuevoRiesgoModal'

const nivelColor: Record<string, string> = { Bajo: 'green', Medio: 'amber', Alto: 'red', Critico: 'red' }

const matrizCellClass: Record<string, string> = {
  Bajo: 'bg-soft-green-bg text-soft-green-text',
  Medio: 'bg-soft-amber-bg text-soft-amber-text',
  Alto: 'bg-soft-red-bg text-soft-red-text',
  Critico: 'bg-soft-red-bg text-soft-red-text',
}

export default function RiesgosPage() {
  const [page, setPage] = useState(0)
  const { data: pagina, isLoading: loading, isFetching, error, refetch } = useRiesgos(page)
  const riesgos = pagina?.data ?? []
  const queryClient = useQueryClient()
  const invalidateRiesgos = () => queryClient.invalidateQueries({ queryKey: riesgosKey })
  const [nuevoOpen, setNuevoOpen] = useState(false)

  const calcularNivel = (p: number, i: number): string => {
    const m = p * i
    if (m <= 2) return 'Bajo'
    if (m <= 4) return 'Medio'
    if (m <= 6) return 'Alto'
    return 'Critico'
  }

  const matrizQuery = useMatrizRiesgos()
  const matriz = matrizQuery.data ?? []

  const getCellLevel = (p: number, i: number): string => {
    const m = p * i
    if (m <= 2) return 'Bajo'
    if (m <= 4) return 'Medio'
    return 'Alto'
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Riesgos" description="Gestión de riesgos del SGC">
        <Button onClick={() => setNuevoOpen(true)}><Plus className="h-4 w-4" /> Nuevo Riesgo</Button>
      </PageHeader>

      <div className="rounded-card border border-qms-border bg-qms-surface p-4">
        <h3 className="mb-4 text-sm font-semibold text-qms-dark">Matriz de Riesgos 3x3</h3>
        {matrizQuery.error && <p role="alert">No se pudo cargar la matriz. <button onClick={() => void matrizQuery.refetch()}>Reintentar</button></p>}
        <div className="grid grid-cols-4 gap-2 text-center text-xs font-medium">
          <div className="text-gray-500">Prob \ Imp</div>
          {[1, 2, 3].map((i) => <div key={i} className="text-gray-500">Impacto {i}</div>)}
          {[1, 2, 3].map((p) => (
            <div key={p} className="contents">
              <div className="text-gray-500">Prob. {p}</div>
              {[1, 2, 3].map((i) => {
                const cell = matriz.find((m) => m.p === p && m.i === i)
                const level = getCellLevel(p, i)
                return (
                  <div key={`${p}-${i}`} className={`flex flex-col items-center justify-center rounded p-3 ${matrizCellClass[level]}`}>
                    <span className="text-lg font-bold">{matrizQuery.isPending || matrizQuery.error ? '—' : cell?.count ?? 0}</span>
                    <span className="text-[10px]">riesgos</span>
                  </div>
                )
              })}
            </div>
          ))}
        </div>
      </div>

      {error ? <p role="alert">No se pudo cargar el listado. <button className="underline" onClick={() => void refetch()}>Reintentar</button></p> : loading ? (
        <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
      ) : (
      <Table>
        <TableHead>
          <tr>
            <TableHeaderCell>Folio</TableHeaderCell>
            <TableHeaderCell>Probabilidad</TableHeaderCell>
            <TableHeaderCell>Impacto</TableHeaderCell>
            <TableHeaderCell>Nivel</TableHeaderCell>
            <TableHeaderCell>Estado</TableHeaderCell>
          </tr>
        </TableHead>
        <tbody>
          {riesgos.length === 0 ? <EmptyState message="No hay riesgos registrados" /> : (
            riesgos.map((r) => (
              <TableRow key={r.id}>
                <TableCell><span className="font-mono text-xs">{r.folio || '-'}</span></TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400">{r.probabilidad}</TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400">{r.impacto}</TableCell>
                <TableCell><Badge variant={nivelColor[r.nivel || ''] || 'gray'}>{r.nivel || calcularNivel(r.probabilidad, r.impacto)}</Badge></TableCell>
                <TableCell className="text-gray-600 dark:text-gray-400">{r.estado}</TableCell>
              </TableRow>
            ))
          )}
        </tbody>
      </Table>
      )}
      <Pagination page={page} count={pagina?.count ?? 0} busy={isFetching} onChange={setPage} />

      <NuevoRiesgoModal open={nuevoOpen} onClose={() => setNuevoOpen(false)} onCreated={() => { invalidateRiesgos() }} />
    </div>
  )
}

app/usuarios/page.tsx:
'use client'

import { useDeferredValue, useEffect, useState } from 'react'
import { Users, UserCheck, UserX, ShieldCheck, Plus, Search, Loader2, Pencil, Trash2, RotateCcw, KeyRound } from 'lucide-react'
import { useQueryClient } from '@tanstack/react-query'
import { useRouter } from 'next/navigation'
import { useUsuarios, usuariosKey, apiFetch, type Usuario } from '@/lib/queries/useUsuarios'
import { useAuthStore } from '@/lib/store/auth-store'
import { showError, showSuccess } from '@/lib/services/errorToast'
import PageHeader from '@/components/ui/PageHeader'
import { Table, TableHead, TableHeaderCell, TableRow, TableCell } from '@/components/ui/Table'
import Badge from '@/components/ui/Badge'
import EmptyState from '@/components/ui/EmptyState'
import Button from '@/components/ui/Button'
import Select from '@/components/ui/Select'
import UsuarioFormModal from '@/components/usuarios/UsuarioFormModal'
import PasswordModal from '@/components/usuarios/PasswordModal'
import ResetPasswordModal from '@/components/usuarios/ResetPasswordModal'
import ConfirmDialog from '@/components/usuarios/ConfirmDialog'

const roles = ['admin', 'calidad', 'colaborador'] as const

const rolLabel: Record<string, string> = { admin: 'Administrador', calidad: 'Calidad', colaborador: 'Colaborador' }
const rolVariant: Record<string, string> = { admin: 'blue', calidad: 'gray', colaborador: 'green' }
const rolBg: Record<string, string> = { admin: 'bg-qms-primary', calidad: 'bg-qms-muted', colaborador: 'bg-qms-success' }

interface StatCard {
  label: string
  value: number
  icon: React.ReactNode
  colorClass: string
  bgClass: string
}

export default function UsuariosPage() {
  const user = useAuthStore((s) => s.user)
  const initialized = useAuthStore((s) => s.initialized)
  const router = useRouter()
  const queryClient = useQueryClient()
  const invalidateUsuarios = () => queryClient.invalidateQueries({ queryKey: usuariosKey })

  const [search, setSearch] = useState('')
  const deferredSearch = useDeferredValue(search)
  const [filtroRol, setFiltroRol] = useState('')
  const [filtroEstado, setFiltroEstado] = useState('')

  const [formOpen, setFormOpen] = useState(false)
  const [formMode, setFormMode] = useState<'crear' | 'editar'>('crear')
  const [usuarioSel, setUsuarioSel] = useState<Usuario | null>(null)
  const [resetSel, setResetSel] = useState<Usuario | null>(null)
  const [pwModal, setPwModal] = useState<{ password: string; title: string; subtitle?: string } | null>(null)
  const [confirmar, setConfirmar] = useState<{ usuario: Usuario; accion: 'desactivar' | 'activar' } | null>(null)
  const [confirmando, setConfirmando] = useState(false)

  useEffect(() => {
    if (!initialized) return
    if (user?.rol !== 'admin') router.replace('/')
  }, [user, initialized, router])

  const { data: usuarios = [], isLoading, isError } = useUsuarios({
    search: deferredSearch,
    rol: filtroRol || undefined,
    estado: filtroEstado || undefined,
  })

  if (!initialized || user?.rol !== 'admin') {
    return <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
  }

  const esAuto = (u: Usuario) => u.id === user?.id

  const total = usuarios.length
  const activos = usuarios.filter((u) => u.estado === 'activo').length
  const inactivos = total - activos
  const admins = usuarios.filter((u) => u.rol === 'admin').length

  const stats: StatCard[] = [
    { label: 'Usuarios', value: total, icon: <Users className="h-5 w-5" />, colorClass: 'text-qms-primary', bgClass: 'bg-soft-blue-bg' },
    { label: 'Activos', value: activos, icon: <UserCheck className="h-5 w-5" />, colorClass: 'text-qms-success', bgClass: 'bg-soft-green-bg' },
    { label: 'Inactivos', value: inactivos, icon: <UserX className="h-5 w-5" />, colorClass: 'text-qms-danger', bgClass: 'bg-soft-red-bg' },
    { label: 'Administradores', value: admins, icon: <ShieldCheck className="h-5 w-5" />, colorClass: 'text-qms-purple', bgClass: 'bg-soft-purple-bg' },
  ]

  function abrirCrear() {
    setFormMode('crear')
    setUsuarioSel(null)
    setFormOpen(true)
  }

  function abrirEditar(u: Usuario) {
    setFormMode('editar')
    setUsuarioSel(u)
    setFormOpen(true)
  }

  function handleFormSuccess(result: { tempPassword?: string }) {
    setFormOpen(false)
    setUsuarioSel(null)
    invalidateUsuarios()
    if (result.tempPassword) {
      setPwModal({
        password: result.tempPassword,
        title: formMode === 'crear' ? 'Usuario creado' : 'Contraseña actualizada',
        subtitle: formMode === 'crear' ? 'Contraseña temporal del nuevo usuario' : 'Nueva contraseña para el usuario',
      })
    }
  }

  async function eliminarUsuario(u: Usuario) {
    if (esAuto(u)) {
      showError(null, 'No puedes eliminar tu propia cuenta')
      return
    }
    const res = await apiFetch('/api/usuarios', {
      method: 'DELETE',
      body: JSON.stringify({ id: u.id }),
    })
    if (res.ok) {
      showSuccess('Usuario eliminado')
      setFormOpen(false)
      setUsuarioSel(null)
      invalidateUsuarios()
    } else {
      const data = await res.json().catch(() => null)
      showError(null, data?.error || 'No se pudo eliminar el usuario')
    }
  }

  async function confirmarCambioEstado() {
    if (!confirmar) return
    const { usuario: u, accion } = confirmar
    setConfirmando(true)
    const res = await apiFetch('/api/usuarios', {
      method: 'PATCH',
      body: JSON.stringify({ id: u.id, estado: accion === 'desactivar' ? 'inactivo' : 'activo' }),
    })
    setConfirmando(false)
    if (res.ok) {
      showSuccess(accion === 'desactivar' ? 'Usuario desactivado' : 'Usuario activado')
      setConfirmar(null)
      invalidateUsuarios()
    } else {
      const data = await res.json().catch(() => null)
      showError(null, data?.error || 'No se pudo cambiar el estado')
    }
  }

  function pedirDesactivar(u: Usuario) {
    if (esAuto(u)) {
      showError(null, 'No puedes desactivar tu propia cuenta')
      return
    }
    setConfirmar({ usuario: u, accion: 'desactivar' })
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Usuarios" description="Gestión de usuarios y accesos del sistema">
        <Button onClick={abrirCrear}><Plus className="h-4 w-4" /> Nuevo usuario</Button>
      </PageHeader>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        {stats.map((s) => (
          <div key={s.label} className="flex items-center gap-3 rounded-card border border-qms-border bg-qms-surface p-4">
            <div className={`flex h-10 w-10 items-center justify-center rounded-lg ${s.bgClass} ${s.colorClass}`}>{s.icon}</div>
            <div>
              <p className="m-0 text-2xl font-bold leading-none text-qms-dark">{s.value}</p>
              <p className="m-0 mt-1 text-xs text-qms-muted">{s.label}</p>
            </div>
          </div>
        ))}
      </div>

      <div className="flex items-center gap-2">
        <div className="relative flex-1 min-w-0">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
          <input
            placeholder="Buscar por nombre o email..."
            className="h-[38px] w-full rounded-button border border-qms-border bg-qms-surface py-2 pl-9 pr-3 text-sm outline-none focus:border-qms-primary focus:ring-1 focus:ring-qms-primary"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <Select value={filtroRol} onChange={(e) => { setFiltroRol(e.target.value); setSearch('') }}>
          <option value="">Todos los roles</option>
          {roles.map((r) => <option key={r} value={r}>{rolLabel[r]}</option>)}
        </Select>
        <Select value={filtroEstado} onChange={(e) => { setFiltroEstado(e.target.value); setSearch('') }}>
          <option value="">Todos los estados</option>
          <option value="activo">Activo</option>
          <option value="inactivo">Inactivo</option>
        </Select>
      </div>

      {isLoading ? (
        <div className="flex min-h-[300px] items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-gray-400" /></div>
      ) : isError ? (
        <EmptyState message="No tienes permisos para ver usuarios" />
      ) : (
        <Table>
          <TableHead>
            <tr>
              <TableHeaderCell>Usuario</TableHeaderCell>
              <TableHeaderCell>Rol</TableHeaderCell>
              <TableHeaderCell>Estado</TableHeaderCell>
              <TableHeaderCell>Último acceso</TableHeaderCell>
              <TableHeaderCell className="text-right">Acciones</TableHeaderCell>
            </tr>
          </TableHead>
          <tbody>
            {usuarios.length === 0 ? (
              <EmptyState message="No hay usuarios registrados" />
            ) : (
              usuarios.map((u) => (
                <TableRow key={u.id}>
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <div
                        className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-sm font-semibold text-white ${rolBg[u.rol] || 'bg-qms-muted'}`}
                      >
                        {u.nombre.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <p className="m-0 text-sm font-medium text-gray-900 dark:text-white">
                          {u.nombre}
                          {esAuto(u) && <span className="ml-2 text-xs font-normal text-qms-muted">(tú)</span>}
                        </p>
                        <p className="m-0 text-xs text-qms-muted">{u.email}</p>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell><Badge variant={rolVariant[u.rol] || 'gray'}>{rolLabel[u.rol] || u.rol}</Badge></TableCell>
                  <TableCell><Badge variant={u.estado === 'activo' ? 'green' : 'red'}>{u.estado === 'activo' ? 'Activo' : 'Inactivo'}</Badge></TableCell>
                  <TableCell className="whitespace-nowrap text-sm text-qms-muted">
                    {u.ultimo_acceso ? new Date(u.ultimo_acceso).toLocaleString('es-ES', { dateStyle: 'short', timeStyle: 'short' }) : '—'}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center justify-end gap-1.5">
                      <Button size="sm" variant="ghost" className="w-[88px] justify-center" onClick={() => abrirEditar(u)}>
                        <Pencil className="h-3.5 w-3.5" /> Editar
                      </Button>
                      <Button size="sm" variant="ghost" className="w-[88px] justify-center" onClick={() => setResetSel(u)}>
                        <KeyRound className="h-3.5 w-3.5" /> Resetear
                      </Button>
                      {u.estado === 'activo' ? (
                        <Button size="sm" variant="ghost" className="w-[88px] justify-center" onClick={() => pedirDesactivar(u)} disabled={esAuto(u)}>
                          <Trash2 className="h-3.5 w-3.5" /> Desactivar
                        </Button>
                      ) : (
                        <Button size="sm" variant="ghost" className="w-[88px] justify-center" onClick={() => setConfirmar({ usuario: u, accion: 'activar' })}>
                          <RotateCcw className="h-3.5 w-3.5" /> Restaurar
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </tbody>
        </Table>
      )}

      <UsuarioFormModal
        open={formOpen}
        mode={formMode}
        usuario={usuarioSel}
        esAuto={usuarioSel ? esAuto(usuarioSel) : false}
        onClose={() => { setFormOpen(false); setUsuarioSel(null) }}
        onSuccess={handleFormSuccess}
        onDelete={eliminarUsuario}
      />

      {pwModal && (
        <PasswordModal
          open={!!pwModal}
          password={pwModal.password}
          title={pwModal.title}
          subtitle={pwModal.subtitle}
          onClose={() => setPwModal(null)}
        />
      )}

      <ResetPasswordModal
        open={!!resetSel}
        usuario={resetSel}
        onClose={() => setResetSel(null)}
        onSaved={() => invalidateUsuarios()}
      />

      <ConfirmDialog
        open={!!confirmar}
        title={confirmar?.accion === 'desactivar' ? 'Desactivar usuario' : 'Activar usuario'}
        message={
          confirmar
            ? confirmar.accion === 'desactivar'
              ? `¿Seguro que deseas desactivar a "${confirmar.usuario.nombre}"? Perderá el acceso al sistema y no podrá iniciar sesión.`
              : `¿Deseas restaurar el acceso de "${confirmar.usuario.nombre}"?`
            : null
        }
        confirmLabel={confirmar?.accion === 'desactivar' ? 'Desactivar' : 'Activar'}
        danger={confirmar?.accion === 'desactivar'}
        loading={confirmando}
        onConfirm={confirmarCambioEstado}
        onCancel={() => { setConfirmar(null); setConfirmando(false) }}
      />
    </div>
  )
}

