'use client'

import { useEffect, useRef } from 'react'

interface ModalProps {
  open: boolean
  onClose: () => void
  title: string
  size?: 'sm' | 'md' | 'lg'
  children: React.ReactNode
}

const sizes: Record<string, string> = {
  sm: 'max-w-[500px]',
  md: 'max-w-[600px]',
  lg: 'max-w-[700px]',
}

export default function Modal({ open, onClose, title, size = 'md', children }: ModalProps) {
  const overlayRef = useRef<HTMLDivElement>(null)
  const onCloseRef = useRef(onClose)
  useEffect(() => { onCloseRef.current = onClose }, [onClose])

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onCloseRef.current()
    }
    if (open) {
      document.addEventListener('keydown', handleEsc)
      document.body.style.overflow = 'hidden'
    }
    return () => {
      document.removeEventListener('keydown', handleEsc)
      document.body.style.overflow = ''
    }
  }, [open])

  if (!open) return null

  return (
    <div
      ref={overlayRef}
      className="fixed inset-0 z-50 flex items-center justify-center overflow-y-auto p-4 bg-black/50"
      onClick={(e) => e.target === overlayRef.current && onClose()}
    >
      <div className={`flex w-full ${sizes[size]} max-h-[90vh] flex-col rounded-modal bg-qms-surface`}>
        <div
          className="flex shrink-0 items-center justify-between rounded-t-modal bg-qms-dark px-4 py-3 text-white"
        >
          <h5 className="m-0 text-sm font-semibold">{title}</h5>
          <button
            type="button"
            onClick={onClose}
            className="flex cursor-pointer items-center justify-center rounded-button border-0 bg-transparent p-1 text-white/40 transition-colors hover:bg-white/10 hover:text-white/70"
          >
            <svg className="h-4 w-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto rounded-b-modal bg-qms-hover-bg px-4 py-3">{children}</div>
      </div>
    </div>
  )
}

components/quejas/AdjuntoPreviewModal.ts:
'use client'

import { useEffect, useRef, useState } from 'react'
import { Download, ExternalLink, FileText, FileQuestion, Loader2, X } from 'lucide-react'
import type { QuejaAdjunto } from '@/lib/queries/useQuejas'
import { supabase } from '@/lib/supabase'
import { descargarAdjuntoQueja } from '@/lib/services/quejaWorkflowService'
import { showError } from '@/lib/services/errorToast'
import { formatBytes } from '@/lib/utils/format'

interface Props {
  adjunto: QuejaAdjunto | null
  onClose: () => void
}

function esDrive(storagePath: string): boolean {
  return !storagePath.includes('/')
}

interface VistaLegacyProps {
  url: string
  mime: string
  nombre: string
}

function VistaLegacy({ url, mime, nombre }: VistaLegacyProps) {
  if (mime.startsWith('image/')) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={url} alt={nombre} className="mx-auto max-h-[80vh] max-w-full rounded-lg" />
    )
  }
  if (mime.startsWith('video/')) {
    return <video controls src={url} className="max-h-[80vh] w-full rounded-lg bg-black" />
  }
  if (mime.startsWith('audio/')) {
    return <audio controls src={url} className="w-full" />
  }
  if (mime === 'application/pdf') {
    return <iframe src={url} title={nombre} className="h-[80vh] w-full rounded-b-lg border-0" />
  }
  return (
    <div className="flex flex-col items-center gap-3 p-10 text-center">
      <FileQuestion className="h-12 w-12 text-gray-300" />
      <p className="text-sm font-medium text-gray-700">{nombre}</p>
      <p className="text-xs text-gray-400">Sin vista previa para este formato ({mime}). Usa el botón Descargar.</p>
    </div>
  )
}

export default function AdjuntoPreviewModal({ adjunto, onClose }: Props) {
  const [legacyUrl, setLegacyUrl] = useState<string | null>(null)
  const [legacyError, setLegacyError] = useState(false)
  const [descargando, setDescargando] = useState(false)
  const onCloseRef = useRef(onClose)
  useEffect(() => { onCloseRef.current = onClose }, [onClose])

  const adjuntoId = adjunto?.id ?? null
  const [prevAdjuntoId, setPrevAdjuntoId] = useState<string | null>(null)
  if (adjuntoId !== prevAdjuntoId) {
    setPrevAdjuntoId(adjuntoId)
    setLegacyUrl(null)
    setLegacyError(false)
  }

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onCloseRef.current()
    }
    if (adjunto) document.addEventListener('keydown', handleEsc)
    return () => document.removeEventListener('keydown', handleEsc)
  }, [adjunto])

  useEffect(() => {
    if (!adjunto || esDrive(adjunto.storage_path)) return
    let alive = true
    supabase.storage
      .from('quejas-adjuntos')
      .createSignedUrl(adjunto.storage_path, 3600)
      .then(({ data, error }) => {
        if (!alive) return
        if (error || !data?.signedUrl) setLegacyError(true)
        else setLegacyUrl(data.signedUrl)
      })
      .catch(() => {
        if (alive) setLegacyError(true)
      })
    return () => { alive = false }
  }, [adjunto])

  if (!adjunto) return null

  const drive = esDrive(adjunto.storage_path)

  const handleDescargar = async () => {
    setDescargando(true)
    try {
      await descargarAdjuntoQueja(adjunto)
    } catch (error) {
      showError(error as Error, 'No se pudo descargar el archivo')
    } finally {
      setDescargando(false)
    }
  }

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center overflow-y-auto p-4 bg-black/60" onClick={onClose}>
      <div className="flex max-h-[95vh] w-full max-w-5xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex shrink-0 items-center gap-2 px-4 py-2.5 text-white bg-qms-dark">
          <FileText className="h-4 w-4 shrink-0 opacity-70" />
          <span className="min-w-0 flex-1 select-text truncate text-sm font-semibold">{adjunto.nombre}</span>
          <span className="hidden whitespace-nowrap text-xs opacity-60 sm:inline">{formatBytes(adjunto.tamano)}</span>
          <span className="rounded border border-white/30 px-1.5 py-0.5 text-[10px] uppercase tracking-wide opacity-80">
            {drive ? 'Google Drive' : 'Interno'}
          </span>
          <button
            type="button"
            onClick={handleDescargar}
            disabled={descargando}
            className="flex shrink-0 cursor-pointer items-center gap-1.5 rounded-lg border border-white/40 px-2.5 py-1 text-xs font-medium transition-colors hover:bg-white/10 disabled:opacity-50"
            title="Descargar"
          >
            {descargando ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
            Descargar
          </button>
          {drive && (
            <a
              href={`https://drive.google.com/file/d/${adjunto.storage_path}/view`}
              target="_blank"
              rel="noreferrer"
              className="hidden shrink-0 rounded-lg border border-white/40 p-1.5 transition-colors hover:bg-white/10 sm:block"
              title="Abrir en Google Drive"
            >
              <ExternalLink className="h-3.5 w-3.5" />
            </a>
          )}
          <button
            type="button"
            onClick={onClose}
            className="shrink-0 cursor-pointer rounded-lg p-1.5 opacity-60 transition-colors hover:bg-white/10 hover:opacity-100"
            title="Cerrar"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="flex min-h-0 flex-1 items-center justify-center overflow-auto bg-qms-hover-bg">
          {drive ? (
            <iframe
              src={`https://drive.google.com/file/d/${adjunto.storage_path}/preview`}
              title={adjunto.nombre}
              className="h-[80vh] w-full rounded-b-xl border-0"
              allow="autoplay"
            />
          ) : legacyUrl ? (
            <div className="w-full p-3">
              <VistaLegacy url={legacyUrl} mime={adjunto.tipo_mime} nombre={adjunto.nombre} />
            </div>
          ) : legacyError ? (
            <div className="flex flex-col items-center gap-2 p-10 text-center">
              <FileQuestion className="h-12 w-12 text-gray-300" />
              <p className="text-sm text-gray-500">No se pudo generar la vista previa de este archivo.</p>
            </div>
          ) : (
            <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
          )}
        </div>
      </div>
    </div>
  )
}

components/quejas/ListaAdjuntos.tsx:
'use client'

import { FileText, Eye, Download, Trash2 } from 'lucide-react'
import Badge from '@/components/ui/Badge'
import { formatBytes } from '@/lib/utils/format'
import type { QuejaAdjunto } from '@/lib/queries/useQuejas'

interface ListaAdjuntosProps {
  adjuntos: QuejaAdjunto[]
  onPreview: (a: QuejaAdjunto) => void
  onDownload: (a: QuejaAdjunto) => void
  puedeEliminar?: (a: QuejaAdjunto) => boolean
  onEliminar?: (a: QuejaAdjunto) => void
}

export default function ListaAdjuntos({
  adjuntos,
  onPreview,
  onDownload,
  puedeEliminar,
  onEliminar,
}: ListaAdjuntosProps) {
  const cliente = adjuntos.filter((a) => !a.usuario_id)
  const analisis = adjuntos.filter((a) => a.usuario_id)

  const renderGrupo = (lista: QuejaAdjunto[], esAnalisis: boolean, titulo: string) => {
    if (lista.length === 0) return null
    return (
      <div className="mt-3">
        <p className="text-xs font-medium text-gray-500 uppercase tracking-wider mb-2">{titulo}</p>
        <ul className="space-y-1">
          {lista.map((a) => (
            <li key={a.id} className="flex select-text items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2">
              <FileText className={`h-4 w-4 shrink-0 ${esAnalisis ? 'text-blue-500' : 'text-gray-400'}`} />
              <button
                type="button"
                onClick={() => onPreview(a)}
                className="min-w-0 flex-1 cursor-pointer truncate text-left text-sm text-gray-700 hover:text-blue-700 hover:underline"
                title="Vista previa"
              >
                {a.nombre}
              </button>
              {esAnalisis && <Badge variant="blue">Análisis</Badge>}
              <span className="shrink-0 whitespace-nowrap text-xs text-gray-400">{formatBytes(a.tamano)}</span>
              <button type="button" onClick={() => onPreview(a)} className="shrink-0 cursor-pointer text-gray-500 hover:text-blue-600" title="Vista previa">
                <Eye className="h-4 w-4" />
              </button>
              <span className="hidden whitespace-nowrap text-xs text-gray-400 sm:inline">
                {new Date(a.created_at).toLocaleDateString('es-ES')}
              </span>
              <button type="button" onClick={() => onDownload(a)} className="shrink-0 cursor-pointer text-gray-500 hover:text-blue-600" title="Descargar">
                <Download className="h-4 w-4" />
              </button>
              {onEliminar && puedeEliminar?.(a) && (
                <button type="button" onClick={() => onEliminar(a)} className="shrink-0 text-gray-400 hover:text-red-600" title="Eliminar adjunto">
                  <Trash2 className="h-4 w-4" />
                </button>
              )}
            </li>
          ))}
        </ul>
      </div>
    )
  }

  return (
    <>
      {renderGrupo(cliente, false, 'Evidencias del cliente')}
      {renderGrupo(analisis, true, 'Evidencias de análisis')}
    </>
  )
}

