'use client'

import { useState } from 'react'
import { Lock, Eye, EyeOff } from 'lucide-react'
import Modal from '@/components/Modal'
import Button from '@/components/ui/Button'
import { supabase } from '@/lib/supabase'
import { showError, showSuccess } from '@/lib/services/errorToast'

interface Props {
  open: boolean
  onClose: () => void
}

export default function CambiarMiPasswordModal({ open, onClose }: Props) {
  const [nueva, setNueva] = useState('')
  const [confirmacion, setConfirmacion] = useState('')
  const [mostrar, setMostrar] = useState(false)
  const [loading, setLoading] = useState(false)

  const valida = (): string | null => {
    if (nueva.length < 8) return 'La contraseña debe tener al menos 8 caracteres.'
    if (nueva !== confirmacion) return 'Las contraseñas no coinciden.'
    return null
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    const errorVal = valida()
    if (errorVal) { showError(null, errorVal); return }
    setLoading(true)
    try {
      const { error } = await supabase.auth.updateUser({ password: nueva })
      if (error) { showError(error, 'No se pudo cambiar la contraseña'); return }
      showSuccess('Contraseña actualizada correctamente')
      setNueva('')
      setConfirmacion('')
      onClose()
    } catch (err) {
      showError(err as Error, 'No se pudo cambiar la contraseña')
    } finally {
      setLoading(false)
    }
  }

  return (
    <Modal open={open} onClose={onClose} title="Cambiar contraseña" size="sm">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-card bg-soft-blue-bg">
            <Lock className="h-5 w-5 text-qms-primary" />
          </div>
          <p className="m-0 text-sm text-qms-muted">
            Define una nueva contraseña para tu cuenta. Debe tener al menos 8 caracteres.
          </p>
        </div>

        {[{
          label: 'Nueva contraseña',
          value: nueva,
          set: setNueva,
          placeholder: 'Mínimo 8 caracteres',
        }, {
          label: 'Confirmar contraseña',
          value: confirmacion,
          set: setConfirmacion,
          placeholder: 'Repite la nueva contraseña',
        }].map((campo) => (
          <div key={campo.label}>
            <label className="mb-1 block text-sm font-medium text-qms-dark">{campo.label}</label>
            <div className="relative">
              <input
                required
                type={mostrar ? 'text' : 'password'}
                placeholder={campo.placeholder}
                className="w-full rounded-button border border-qms-border bg-qms-surface px-3 py-2 pr-9 text-sm outline-none focus:border-qms-primary focus:ring-1 focus:ring-qms-primary"
                value={campo.value}
                onChange={(e) => campo.set(e.target.value)}
              />
              <button
                type="button"
                onClick={() => setMostrar((v) => !v)}
                className="absolute right-2 top-1/2 flex -translate-y-1/2 cursor-pointer items-center justify-center border-0 bg-transparent text-qms-muted"
                title={mostrar ? 'Ocultar contraseña' : 'Mostrar contraseña'}
              >
                {mostrar ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>
        ))}

        <div className="flex justify-end gap-3 pt-1">
          <Button type="button" variant="secondary" onClick={onClose}>Cancelar</Button>
          <Button type="submit" variant="primary" loading={loading}>Actualizar</Button>
        </div>
      </form>
    </Modal>
  )
}

components/usuarios/PasswordModal.tsx:
'use client'

import { Key, Copy, Check } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import Modal from '@/components/Modal'
import Button from '@/components/ui/Button'
import { showError, showSuccess } from '@/lib/services/errorToast'

interface PasswordModalProps {
  open: boolean
  password: string
  title: string
  subtitle?: string
  onClose: () => void
}

export default function PasswordModal({ open, password, title, subtitle, onClose }: PasswordModalProps) {
  const [copied, setCopied] = useState(false)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => () => { if (timeoutRef.current) clearTimeout(timeoutRef.current) }, [])

  const handleCopy = () => {
    navigator.clipboard.writeText(password).then(
      () => {
        setCopied(true)
        showSuccess('Contraseña copiada')
        if (timeoutRef.current) clearTimeout(timeoutRef.current)
        timeoutRef.current = setTimeout(() => setCopied(false), 2000)
      },
      () => showError(null, 'No se pudo copiar la contraseña')
    )
  }

  return (
    <Modal open={open} onClose={onClose} title={title} size="sm">
      <div className="space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-card bg-soft-blue-bg">
            <Key className="h-5 w-5 text-qms-primary" />
          </div>
          <div>
            <p className="m-0 text-sm font-semibold text-qms-dark">Contraseña generada</p>
            {subtitle && <p className="m-0 text-xs text-qms-muted">{subtitle}</p>}
          </div>
        </div>
        <div className="flex items-center gap-2 rounded-card border border-qms-border bg-qms-surface px-3 py-2.5">
          <span className="flex-1 break-all font-mono text-sm text-qms-dark tracking-wide">{password}</span>
          <button
            type="button"
            onClick={handleCopy}
            className={`flex cursor-pointer items-center gap-1 rounded-button border-0 px-2 py-1 text-xs font-medium transition-colors ${copied ? 'bg-green-50 text-green-700' : 'bg-soft-blue-bg text-qms-primary'}`}
          >
            {copied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
            {copied ? 'Copiada' : 'Copiar'}
          </button>
        </div>
        <p className="m-0 text-xs text-qms-muted">
          Comparte esta contraseña de forma segura. No volverá a mostrarse.
        </p>
        <div className="flex justify-end">
          <Button type="button" variant="primary" onClick={onClose}>Entendido</Button>
        </div>
      </div>
    </Modal>
  )
}

