        .from('permisos')
        .upsert({ rol: permiso.rol, modulo: permiso.modulo, leer: permiso.leer, escribir: permiso.escribir })
      if (error) throw error
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: permisosKey })
    },
  })
}

